INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (188, 1, '설정 값의 출처 보기', '같은 `user.name` 이 전역 파일과 저장소 설정에 모두 있을 때, 각 값이 어느 파일에서 왔는지 보려면 어떻게 할까요?', '출처를 보여 주는 옵션이 있어요.', NULL, NULL, '[]', 'choice', '["`git config --where user.name` 으로 본다", "`git log --config user.name` 으로 본다", "`git config --show-origin --get-all user.name` 으로 보면 값마다 `file:경로` 가 앞에 붙어 전역 파일과 `.git/config` 가 구분된다", "`git status --origin` 으로 본다"]', 2, '`--show-scope` 를 쓰면 파일 경로 대신 `global`, `local` 같은 범위 이름이 나옵니다.', NULL, NULL, NULL, NULL),
  (188, 2, '범위가 다를 때 우선순위', '`user.name` 이 전역에는 `G`, 저장소(local)에는 `L` 로 설정되어 있습니다. 저장소 안에서 `git config user.name` 과 `git config --global user.name` 은 각각 무엇을 출력할까요?', '더 좁은 범위가 이겨요.', NULL, NULL, '[]', 'choice', '["둘 다 `G` 를 출력한다", "`git config user.name` 은 `L`(저장소 설정이 전역보다 우선), `git config --global user.name` 은 `G` 를 출력한다. `--list` 에는 전역 값이 먼저, 저장소 값이 나중에 나오고 나중 값이 적용된다", "둘 다 `L` 을 출력한다", "전역 값이 항상 우선하므로 `git config user.name` 은 `G` 이다"]', 1, '`--list --show-scope` 로 `global`, `local` 순서를 확인할 수 있습니다.', NULL, NULL, NULL, NULL),
  (188, 3, '없는 키 조회', '설정에 없는 키를 `git config --get nokey.x` 로 조회하면 어떻게 될까요? 대신 기본값을 쓰려면요?', '출력은 없고 종료 코드로 알려요.', NULL, NULL, '[]', 'choice', '["아무것도 출력하지 않고 종료 코드 1 로 끝난다. `git config --get --default fallback nokey.x` 처럼 `--default` 를 주면 `fallback` 이 출력된다", "`error: key not found` 를 출력하고 종료 코드 128 이다", "빈 줄을 출력하고 종료 코드 0 이다", "설정 파일에 `nokey.x` 가 자동으로 만들어진다"]', 0, '스크립트에서는 종료 코드 1 로 키가 없음을 판단할 수 있습니다.', NULL, NULL, NULL, NULL),
  (188, 4, '값이 여러 개인 키', '`git config --add multi.k a` 와 `--add multi.k b` 를 한 뒤 `git config multi.k c` 를 하면 어떻게 될까요? 하나로 합치려면요?', '한 값으로 덮어쓸 수 없어요.', NULL, NULL, '[]', 'choice', '["마지막 값 `b` 만 `c` 로 바뀐다", "`a`, `b`, `c` 세 값이 된다", "아무 오류 없이 전체가 `c` 하나로 바뀐다", "`cannot overwrite multiple values with a single value` 오류와 종료 코드 5 로 실패하고 값은 그대로 `a`, `b` 이다. `--replace-all` 로 바꾸거나 `--unset-all` 로 지워야 한다"]', 3, '`git config --get-all multi.k` 로 모든 값을 줄마다 볼 수 있습니다.', NULL, NULL, NULL, NULL),
  (188, 5, '--type 으로 값 해석', '`git config t.flag yes` 와 `git config t.n 1k` 를 한 뒤 `--type=bool` 과 `--type=int` 로 읽으면 각각 무엇이 나올까요?', '저장된 글자는 그대로이고 읽을 때 해석해요.', NULL, NULL, '[]', 'choice', '["`--type=bool` 은 `yes` 를 그대로 출력한다", "`--type=int` 는 `1k` 를 `1000` 으로 바꾼다", "`git config --type=bool t.flag` 는 `true`, `git config --type=int t.n` 은 `1024`(k 는 1024 배) 이다. 형식 없이 읽으면 저장된 글자 `yes` 가 그대로 나온다", "`--type` 은 파일에 저장된 값 자체를 바꾼다"]', 2, '`1k` 는 1024, `1m` 은 1048576, `1g` 는 1073741824 로 해석됩니다.', NULL, NULL, NULL, NULL),
  (188, 6, '한 번만 쓰는 설정 -c', '`git -c user.name=TMP config --get user.name` 을 실행한 뒤 일반 `git config --get user.name` 을 실행하면 값이 어떨까요?', '명령줄 값은 그 명령에만 적용돼요.', NULL, NULL, '[]', 'choice', '["`-c` 의 값이 `.git/config` 에 저장되어 계속 남는다", "앞 명령은 `TMP` 를 출력하지만 파일에 저장되지는 않아서 뒤 명령은 원래 저장된 값(예: `L`)을 출력한다. `-c` 를 같은 키로 두 번 주면 나중 값이 적용되고 `--get-all` 에는 둘 다 보인다", "`-c` 의 값이 전역 파일에 저장된다", "`-c` 는 `git config` 에서는 쓸 수 없다"]', 1, '환경 변수 `GIT_CONFIG_COUNT`, `GIT_CONFIG_KEY_0`, `GIT_CONFIG_VALUE_0` 으로도 한 번만 쓰는 설정을 줄 수 있습니다.', NULL, NULL, NULL, NULL),
  (188, 7, '별칭에서 셸 명령 쓰기', '`git config alias.who ''!echo shell-alias''` 를 하고 `git who` 를 실행하면 어떻게 될까요? 별칭에 인자를 넘기려면요?', '앞의 느낌표가 의미를 바꿔요.', NULL, NULL, '[]', 'choice', '["`!` 로 시작하는 별칭은 git 하위 명령이 아니라 셸 명령으로 실행되어 `shell-alias` 가 출력된다. 인자를 쓰려면 `!f() { echo \\"arg:$1\\"; }; f` 처럼 함수로 감싸면 `git say hello` 가 `arg:hello` 를 출력한다", "`!` 는 별칭을 비활성화한다는 뜻이다", "`git who` 는 `unknown command` 오류가 난다", "셸 별칭은 인자를 받을 수 없다"]', 0, '일반 별칭(`rev-list --count`)은 뒤에 쓴 인자(`HEAD`)가 그대로 이어 붙습니다.', NULL, NULL, NULL, NULL),
  (188, 8, '기본 명령을 별칭으로 덮을 수 있을까', '`git config alias.status ''log --oneline''` 을 한 뒤 `git status` 를 실행하면 무엇이 실행될까요?', '원래 있는 명령이 먼저예요.', NULL, NULL, '[]', 'choice', '["`git log --oneline` 이 실행된다", "별칭 이름이 겹친다는 오류로 실패한다", "설정할 때 이미 거부된다", "별칭은 무시되고 원래의 `git status` 가 실행된다 (`On branch master` 로 시작하는 출력). git 은 이미 있는 내장 명령 이름의 별칭을 사용하지 않는다"]', 3, '기본 명령과 겹치지 않는 이름(`st`, `l`)을 별칭으로 씁니다.', NULL, NULL, NULL, NULL),
  (188, 9, '환경 변수와 core.pager', '`git config core.pager ''less -F''` 로 설정한 상태에서 `git var GIT_PAGER` 와 `GIT_PAGER=cat git var GIT_PAGER` 는 각각 무엇을 출력할까요?', '환경 변수가 설정 파일보다 앞서요.', NULL, NULL, '[]', 'choice', '["둘 다 `less -F` 이다", "둘 다 `cat` 이다", "앞은 `less -F`, 뒤는 `cat` 이다. 환경 변수 `GIT_PAGER` 가 `core.pager` 설정보다 우선한다", "환경 변수는 `core.pager` 를 바꿀 수 없어 뒤도 `less -F` 이다"]', 2, '같은 방식으로 `GIT_EDITOR` 환경 변수는 `git var GIT_EDITOR` 의 결과를 정합니다.', NULL, NULL, NULL, NULL),
  (188, 10, 'include.path 의 상대 경로', '`.git/config` 에 `include.path = ../../extra.cfg` 를 쓰면 그 상대 경로는 무엇을 기준으로 해석될까요? 포함된 값의 출처는 어떻게 보일까요?', '설정을 담은 파일 자리가 기준이에요.', NULL, NULL, '[]', 'choice', '["명령을 실행한 현재 폴더가 기준이다", "그 줄이 들어 있는 설정 파일(`.git/config`)이 있는 폴더가 기준이어서 `.git` 의 두 단계 위(저장소 바깥)의 `extra.cfg` 를 읽는다. `--show-origin` 에는 `file:.git/../../extra.cfg` 처럼 보이고 값 `fromfile` 이 조회된다", "항상 홈 폴더가 기준이다", "상대 경로는 쓸 수 없고 절대 경로만 가능하다"]', 1, '포함된 파일의 값도 일반 설정처럼 `git config --get 키` 로 읽힙니다.', NULL, NULL, NULL, NULL),
  (188, 11, 'includeIf gitdir 조건', '전역 설정에 `includeIf.gitdir:<저장소 폴더>/.path = cond.cfg` 를 두면, 그 폴더 안 저장소와 다른 폴더의 저장소에서 `cond.cfg` 의 값은 각각 어떻게 보일까요?', '조건에 맞는 저장소에서만 포함돼요.', NULL, NULL, '[]', 'choice', '["그 폴더 아래의 저장소에서는 `cond.cfg` 의 값이 조회되고, 다른 폴더의 저장소에서는 조회되지 않는다(종료 코드 1). 폴더 끝에 `/` 를 붙인 패턴은 그 아래 전체에 맞는다", "모든 저장소에서 조회된다", "어느 저장소에서도 조회되지 않는다", "다른 폴더의 저장소에서도 조회되지만 값이 비어 있다"]', 0, '조건에 맞지 않는 저장소에서는 포함 파일의 값이 보이지 않습니다.', NULL, NULL, NULL, NULL),
  (188, 12, 'includeIf onbranch 조건', '`includeIf.onbranch:master.path = br.cfg` 를 저장소 설정에 두고, `master` 와 `dev` 브랜치에서 `br.cfg` 의 값을 조회하면 어떻게 될까요?', '현재 브랜치 이름이 조건이에요.', NULL, NULL, '[]', 'choice', '["브랜치와 상관없이 항상 조회된다", "`dev` 에서도 조회된다", "`onbranch` 는 저장소가 아니라 전역 설정에서만 쓸 수 있다", "`master` 브랜치에서는 `br.cfg` 의 값이 조회되고 `dev` 로 바꾸면 조회되지 않는다(종료 코드 1). 브랜치 이름에 따라 포함 여부가 바뀐다"]', 3, '조건은 설정을 읽는 시점의 현재 브랜치로 판단합니다.', NULL, NULL, NULL, NULL),
  (188, 13, 'url.insteadOf', '`git config url.<새접두어>.insteadOf <옛접두어>` 를 설정하면 `git remote get-url` 과 `git config --get remote.o.url` 의 결과는 각각 어떨까요?', '저장된 값과 실제 사용 값이 달라요.', NULL, NULL, '[]', 'choice', '["두 명령 모두 새 주소를 보여 준다", "두 명령 모두 원래 주소를 보여 준다", "`git remote get-url o` 는 접두어가 바뀐 새 주소를 보여 주고, `git config --get remote.o.url` 은 저장된 원래 주소를 그대로 보여 준다. 설정 파일의 원격 주소는 바뀌지 않는다", "`remote.o.url` 이 새 주소로 자동으로 다시 쓰인다"]', 2, '설정 파일에 저장된 원래 주소와 실제로 쓰이는 주소가 다를 수 있습니다.', NULL, NULL, NULL, NULL),
  (188, 14, '대소문자 규칙', '`git config S.Sub.Key 2` 로 저장한 뒤 `git config --get s.Sub.key` 와 `git config --get s.sub.key` 는 각각 어떻게 될까요?', '섹션과 변수 이름은 구분하지 않지만 중간 이름은 구분해요.', NULL, NULL, '[]', 'choice', '["둘 다 `2` 를 출력한다", "`s.Sub.key` 는 `2` 를 출력하고, `s.sub.key` 는 아무것도 출력하지 않고 종료 코드 1 이다. 섹션 이름과 변수 이름은 대소문자를 구분하지 않지만 서브섹션(가운데 `Sub`)은 구분한다. 목록에는 `s.Sub.key=2` 로 보인다", "둘 다 아무것도 출력하지 않는다", "섹션 이름은 대소문자를 구분해 `S` 로만 조회된다"]', 1, '`core.foo` 를 `Core.Foo` 로 저장해도 `git config core.foo` 로 읽힙니다.', NULL, NULL, NULL, NULL),
  (188, 15, '사용자 이름 설정', '이 저장소에만 적용되는 사용자 이름을 `tester` 로 설정하는 명령을 채우세요.', '이름을 설정하는 키는 `user.name` 이에요.', NULL, NULL, '[]', 'fill', '["user.name", "user.fullname", "git.name", "author.name"]', NULL, '범위 옵션 없이 쓰면 현재 저장소의 `.git/config` 에 저장됩니다.', '[0]', 'git config {0} tester', NULL, NULL),
  (188, 16, '전역 범위 지정', '모든 저장소에 적용되는 전역 설정으로 `user.email` 을 저장하는 옵션을 채우세요.', '"세계"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--global", "--local", "--all", "--system-wide"]', NULL, '`--local` 은 저장소, `--global` 은 사용자, `--system` 은 컴퓨터 전체입니다.', '[0]', 'git config {0} user.email a@b', NULL, NULL),
  (188, 17, '출처와 함께 보기', '설정 값을 파일 경로와 함께 보도록 `--list` 에 붙이는 옵션을 채우세요.', '"출처 보이기"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--show-origin", "--show-path", "--source", "--where"]', NULL, '`--show-scope` 는 `global`, `local` 같은 범위를 보여 줍니다.', '[0]', 'git config --list {0}', NULL, NULL),
  (188, 18, '기본값 지정', '없는 키를 조회할 때 `fallback` 을 대신 출력하게 하는 옵션을 채우세요.', '"기본값"을 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["--default", "--else", "--fallback", "--or"]', NULL, '키가 있으면 저장된 값이 그대로 출력됩니다.', '[0]', 'git config --get {0} fallback nokey.x', NULL, NULL),
  (188, 19, '값 전부 보기', '같은 키에 저장된 값을 모두 한 줄씩 출력하는 옵션을 채우세요.', '"모두 가져오기"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--get-all", "--list-all", "--all", "--get-every"]', NULL, '`--get` 은 값이 여러 개일 때 마지막 값을 출력합니다.', '[0]', 'git config {0} multi.k', NULL, NULL),
  (188, 20, '값 하나 더 추가', '기존 값을 유지한 채 같은 키에 값을 하나 더 추가하는 옵션을 채우세요.', '"더하기"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["--add", "--append", "--push", "--plus"]', NULL, '추가하지 않고 같은 키로 쓰면 값이 하나일 때만 덮어쓰기가 됩니다.', '[0]', 'git config {0} multi.k b', NULL, NULL),
  (188, 21, '모두 지우기', '같은 키의 값이 여러 개일 때 한꺼번에 모두 지우는 옵션을 채우세요.', '`--unset` 에 "모두"를 붙인 모양이에요.', NULL, NULL, '[]', 'fill', '["--unset-all", "--delete-all", "--remove-all", "--clear"]', NULL, '`--unset` 만 쓰면 값이 여러 개일 때 실패합니다.', '[0]', 'git config {0} multi.k', NULL, NULL),
  (188, 22, '섹션 통째로 지우기', '`z` 섹션의 모든 키를 한꺼번에 지우는 옵션을 채우세요.', '섹션을 지운다는 뜻의 영어 단어 조합이에요.', NULL, NULL, '[]', 'fill', '["--remove-section", "--unset-section", "--delete-section", "--drop"]', NULL, '섹션 이름을 바꿀 때는 `--rename-section 이전 새이름` 을 씁니다.', '[0]', 'git config {0} z', NULL, NULL),
  (188, 23, '셸 별칭 만들기', '`git who` 를 실행하면 셸 명령이 실행되도록 별칭 값 앞에 붙이는 기호를 채우세요.', '명령 앞에 붙이는 느낌표예요.', NULL, NULL, '[]', 'fill', '["!", "$", "#", "@"]', NULL, '이렇게 만든 별칭은 git 하위 명령이 아니라 셸 명령으로 실행됩니다.', '[0]', 'git config alias.who ''{0}echo hi''', NULL, NULL),
  (188, 24, '한 번만 쓰는 설정', '설정 파일에 저장하지 않고 이 명령 한 번에만 `user.name` 을 `TMP` 로 쓰는 옵션을 채우세요.', 'git 바로 뒤에 한 글자 옵션을 써요.', NULL, NULL, '[]', 'fill', '["-c", "-C", "-s", "-o"]', NULL, '저장되지 않으므로 다음 명령에는 영향이 없습니다.', '[0]', 'git {0} user.name=TMP commit -m msg', NULL, NULL),
  (188, 25, '특정 파일의 설정 읽기', '저장소 설정이 아니라 지정한 파일 `f.cfg` 의 `a.b` 를 읽는 옵션을 채우세요.', '"파일"이라는 뜻의 한 글자 옵션이에요.', NULL, NULL, '[]', 'fill', '["-f", "-p", "-i", "-o"]', NULL, '`--file f.cfg` 로 길게 써도 같은 뜻입니다.', '[0]', 'git config {0} f.cfg --get a.b', NULL, NULL),
  (188, 26, '설정이 어디서 왔는지 찾기', '이상한 `user.email` 이 어디에서 설정됐는지 찾는 순서입니다. 순서에 맞게 놓아 보세요.', '값 확인 → 출처 확인 → 수정 순서예요.', NULL, NULL, '[]', 'order', '["`git config --get user.email` 로 지금 적용되는 값을 확인한다", "`git config --show-origin --get-all user.email` 로 값이 정해진 파일을 확인한다", "`git config --show-scope --get-regexp ''^user\\\\.''` 로 어느 범위의 값인지 확인한다", "해당 범위에 맞게 `--local` 또는 `--global` 옵션으로 값을 고치거나 `--unset` 한다"]', NULL, '값이 여러 파일에 있으면 나중에 읽는(더 좁은 범위의) 값이 적용됩니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (188, 27, '프로젝트별 이메일 분리하기', '회사 폴더 아래 저장소에서만 다른 이메일을 쓰는 순서입니다. 순서에 맞게 놓아 보세요.', '파일 만들기 → 조건 연결 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["회사용 설정 파일을 만들어 `[user]` 아래 `email` 을 적는다", "전역 설정에 `includeIf.gitdir:폴더/.path` 로 그 파일을 연결한다", "회사 폴더 아래 저장소에서 `git config --get user.email` 이 회사용 값인지 확인한다", "다른 폴더의 저장소에서는 기존 값이 그대로인지 확인한다"]', NULL, '조건 폴더 끝의 `/` 를 빠뜨리지 않도록 주의하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (188, 28, '값이 여러 개일 때 하나로 정리하기', '`multi.k` 에 값이 여러 개일 때 하나로 정리하는 순서입니다. 순서에 맞게 놓아 보세요.', '확인 → 실패 확인 → 교체 → 재확인 순서예요.', NULL, NULL, '[]', 'order', '["`git config --get-all multi.k` 로 값이 여러 개임을 확인한다", "`git config multi.k c` 가 종료 코드 5 로 실패함을 확인한다", "`git config --replace-all multi.k z` 로 모든 값을 하나로 바꾼다", "`git config --get-all multi.k` 로 `z` 하나만 남았는지 확인한다"]', NULL, '모두 지우려면 `--unset-all` 을 씁니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (188, 29, '별칭 만들고 쓰기', '자주 쓰는 명령을 별칭으로 만들어 쓰는 순서입니다. 순서에 맞게 놓아 보세요.', '설정 → 사용 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`git config alias.st ''status -s''` 로 별칭을 저장한다", "`git st` 로 별칭을 실행해 짧은 상태가 나오는지 본다", "`git config --get alias.st` 로 저장된 값을 확인한다", "필요 없으면 `git config --unset alias.st` 로 지운다"]', NULL, '별칭은 전역에 두면 모든 저장소에서 쓸 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
